private Optional<SessionRunConfigurationSource.RunConfiguration> activeRunConfiguration(
        SessionSnapshot current) {
    if (!(configuration.sessionRepository() instanceof SessionRunConfigurationSource source)) {
        return Optional.empty();
    }
    Optional<SessionRunConfigurationSource.RunConfiguration> captured =
            source.activeRunConfiguration(current.sessionId());
    if (current.activeRun().isPresent() && captured.isEmpty()) {
        throw new IllegalStateException("active Run has no captured configuration");
    }
    return captured;
}

